action.code:
const void *key = argkey;
const void *data = argdata;
size_t hashes[2];
size_t bucket = argbucket;
size_t tbucket;
unsigned i;
unsigned max_iterations = 1000;

while (max_iterations-- > 0) {
    i = (unsigned)prng_lg_range_u64(&ckh->prng_state, LG_CKH_BUCKET_CELLS);
    ckhc_t *cell = &ckh->tab[(bucket << LG_CKH_BUCKET_CELLS) + i];

    if (cell->key == NULL) {
        cell->key = key;
        cell->data = data;
        ckh->count++;
        return false;
    }

    const void *tkey = cell->key;
    const void *tdata = cell->data;
    cell->key = key;
    cell->data = data;
    key = tkey;
    data = tdata;

#ifdef CKH_COUNT
    ckh->nrelocs++;
#endif

    ckh->hash(key, hashes);
    tbucket = hashes[1] & ((ZU(1) << ckh->lg_curbuckets) - 1);

    if (tbucket == bucket) {
        tbucket = hashes[0] & ((ZU(1) << ckh->lg_curbuckets) - 1);
    }

    if (tbucket == argbucket) {
        return true;
    }

    bucket = tbucket;
}

return true;

